TOPIC_L2_QUESTIONS = {1: [{'q': "<b>Question 1 (Foundation):</b> Write in figures: 'Six hundred and forty-two thousand, and eighty-five'. Then order these populations from smallest to largest: 485,200; 458,900; 485,090; 502,100.", 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A regional distribution hub processed 425,800 parcels in Q1 and 389,950 parcels in Q2. How many more parcels were processed in Q1 than in Q2?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A council has an annual housing budget of £1,250,000. It spends £485,600 on roof repairs, £392,450 on heating upgrades, and £184,200 on external insulation. How much budget remains unspent?', 'marks': 4, 'weight': 1.4}], 2: [{'q': '<b>Question 1 (Foundation):</b> Order these values from coldest to warmest: -12°C, +3°C, -4.5°C, -0.5°C, +1.8°C, -15°C.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A warehouse chiller is set at +3°C. A fault causes the temperature to drop by 8.5°C. What is the new temperature? If the safety alarm triggers at -5°C, does the alarm sound?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A small business starts Monday with a bank balance of -£640. Over the week: sales revenue of +£2,850 is paid in, direct debits of £1,420 and £980 clear, and a supplier refund of £195 arrives. What is the Friday closing balance?', 'marks': 4, 'weight': 1.4}], 3: [{'q': '<b>Question 1 (Foundation):</b> Evaluate giving your answers in simplest form: a) 5/8 + 1/6 &emsp; b) 2 2/3 × 3/4.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A chef has 4 1/2 kg of prime beef mince. Each burger patty requires 3/16 kg of mince. How many complete burger patties can the chef make?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> In a manufacturing plant, 3/5 of workers are on day shift, 1/4 are on late shift, and the remaining 45 workers are on night shift. How many total workers are employed at the plant?', 'marks': 4, 'weight': 1.4}], 4: [{'q': '<b>Question 1 (Foundation):</b> Write the single decimal multiplier for: a) Finding 6.5% &emsp; b) Increasing by 12% &emsp; c) Decreasing by 35% &emsp; d) Decreasing by 4%.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A car insurance premium of £620.00 increases by 8.5% at renewal. What is the new renewal price?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A distribution depot ships 14,500 parcels in November. In December, parcel volume increases by 28%. In January, volume drops by 15% compared to December. How many parcels are shipped in January?', 'marks': 4, 'weight': 1.4}], 5: [{'q': '<b>Question 1 (Foundation):</b> A power drill sells for £84.00 including 20% VAT. Calculate the price before VAT was added.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A bakery sold 450 loaves on Friday and 558 loaves on Saturday. Calculate the percentage increase in sales.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A fitness coach bought commercial gym equipment for £3,200. Three years later, he sells it for £1,840. Calculate the percentage loss in value. If a new model is currently advertised at £2,760 after a 15% discount, what was its original price?', 'marks': 4, 'weight': 1.4}], 6: [{'q': '<b>Question 1 (Foundation):</b> Calculate the value of £2,400 invested for 2 years at 3% compound interest per annum.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A commercial delivery van was purchased brand new for £28,000. It depreciates at a rate of 18% per year. What is its estimated book value after 3 years?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> An investor has £10,000 to invest for 3 years. Bank A offers 4.5% simple interest per year. Bank B offers 4.2% compound interest per annum. Which bank will yield more total interest at the end of 3 years, and by how much?', 'marks': 4, 'weight': 1.4}], 7: [{'q': '<b>Question 1 (Foundation):</b> Share £4,500 in the ratio 5 : 3 : 1.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A mortar mix uses cement, sand, and gravel in the ratio 1 : 2 : 4. A builder needs 1.4 tonnes of mortar. How many kilograms of sand does he require?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> Supermarket A sells a 750 g box of cereal for £2.85. Supermarket B sells a 1.2 kg family pack for £4.32. Which pack offers better value for money? Justify your decision with full unit calculations.', 'marks': 4, 'weight': 1.4}], 8: [{'q': '<b>Question 1 (Foundation):</b> It takes 5 cleaners 4 hours to clean an office floor. How long would it take 8 cleaners working at the exact same rate?', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A pipe delivers 45 litres/minute and fills a water storage tank in 80 minutes. How long would it take to fill the tank if the flow rate was reduced to 30 litres/minute?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A groundworks contractor estimates that 3 excavators can clear a development site in 16 working days. The client requests the work be completed in 6 working days. How many additional excavators must the contractor hire?', 'marks': 4, 'weight': 1.4}], 9: [{'q': '<b>Question 1 (Foundation):</b> Evaluate without a calculator: a) 4.85 × 100 &emsp; b) 73.6 ÷ 1000 &emsp; c) 14.6 - 8.79.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A dental receptionist checks three utility payments: electricity £184.25, gas £112.80, and water £46.45. If the practice had budgeted £350.00, by how much did they overspend or underspend?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> An electrician quotes a client: 6 light fittings at £24.50 each, 45 m cable at £1.20/m, and 3.5 hours labour at £35/hr. The electrician offers a 10% prompt-payment discount on the total before VAT, and then adds 20% VAT. Calculate the final bill.', 'marks': 4, 'weight': 1.4}], 10: [{'q': '<b>Question 1 (Foundation):</b> Evaluate without a calculator: a) 15 - 3 × 4 + 2 &emsp; b) (8 + 4) ÷ (7 - 3) + 3².', 'marks': 2}, {'q': "<b>Question 2 (Workplace Problem):</b> Engineer's braking distance formula: d = 0.05v² + 0.4v, where v is speed in mph. Calculate the stopping distance d when v = 40 mph.", 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> Total hire charge C (in £) for an industrial generator is given by C = 1.20 × (65 + 35d - 20), where d is the number of days hired. Calculate C for an 8-day hire.', 'marks': 4, 'weight': 1.4}], 11: [{'q': '<b>Question 1 (Foundation):</b> Round each number to 1 significant figure to estimate: a) 48.7 × 31.2 &emsp; b) 812 ÷ 19.6.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A warehouse manager orders 195 heavy-duty crates at £48.75 each. Use 1 significant figure estimation to find an approximate total cost, and state whether it is an overestimate or underestimate.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A parcel courier measures a crate as 60 cm by 40 cm by 30 cm, each rounded to the nearest 10 cm. Calculate the upper bound (maximum possible volume) of the crate in cm³.', 'marks': 4, 'weight': 1.4}], 12: [{'q': '<b>Question 1 (Foundation):</b> Convert: a) 3.45 kg into grams &emsp; b) 750 ml into litres &emsp; c) 140 miles into kilometres using 5 miles = 8 km.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A patient in hospital is prescribed liquid medication: 15 ml three times per day for 14 days. Will a 500 ml bottle be sufficient? Show full working.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A UK haulage truck carries 14 tonnes of gravel. The European delivery limit is 31,000 lbs. Use 1 kg = 2.2 lbs to determine if the truck is within legal weight limits.', 'marks': 4, 'weight': 1.4}], 13: [{'q': '<b>Question 1 (Foundation):</b> A brass casting has a volume of 250 cm³ and a mass of 2,125 g. Calculate the density of the brass in g/cm³.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A hydraulic piston exerts a force of 1,800 N on an area of 0.04 m². Calculate the pressure exerted in N/m².', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A sales rep travels from Leeds to Birmingham (115 miles). He departs at 07:45 and arrives at 10:09. Due to roadworks, he had to stop for a 15-minute coffee break. Calculate his average driving speed while moving.', 'marks': 4, 'weight': 1.4}], 14: [{'q': '<b>Question 1 (Foundation):</b> An L-shaped office has overall length 12 m and overall width 9 m. Find the total perimeter of the room.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A rectangular warehouse yard measures 28 m by 18 m, with a 4 m wide vehicle entrance gate where no fencing is required. Security fencing costs £32.50 per metre. Calculate the cost of the fencing.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A T-shaped exhibition stand has a top bar of 10 m by 3 m and a central stem of 4 m wide by 6 m long. Aluminium edging strip is sold in 2.5 m lengths at £14.00 per length. How many lengths are needed for the full outer perimeter, and what is the total cost?', 'marks': 4, 'weight': 1.4}], 15: [{'q': '<b>Question 1 (Foundation):</b> Calculate the circumference of a circular water tank with a radius of 4.5 metres. (Use π = 3.14)', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A running track consists of a rectangle measuring 100 m by 64 m with two semicircular ends. Calculate the total running distance around the outer edge of one complete lap.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A decorative wrought-iron garden gate has a rectangular base (1.2 m wide by 1.8 m high) topped with a semicircular arch. What total length of iron framing is needed for the perimeter? (Use π = 3.142)', 'marks': 4, 'weight': 1.4}], 16: [{'q': '<b>Question 1 (Foundation):</b> Calculate the area of: a) A triangle with base 14 cm and perpendicular height 9 cm &emsp; b) A parallelogram with base 8.5 m and perpendicular height 4.0 m.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A rectangular gable wall is 8 m wide and 5 m high, topped by a triangular roof section of base 8 m and vertical height 2.5 m. Calculate the total exterior wall area to be rendered.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A rectangular hallway measures 12 m by 3.5 m. Square ceramic floor tiles measure 50 cm by 50 cm and are sold in boxes of 8 tiles for £22.00 per box. Adding 10% extra tiles for cutting wastage, calculate the total cost of the boxes required.', 'marks': 4, 'weight': 1.4}], 17: [{'q': '<b>Question 1 (Foundation):</b> Calculate the area of a circular patio with a diameter of 6 metres. Give your answer to 2 decimal places. (Use π = 3.142)', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A flat roof in the shape of a trapezium has parallel sides of 7.2 m and 11.8 m, and a perpendicular width of 5.0 m. Roofing felt costs £8.50 per square metre. Calculate the cost to felt the roof.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A sports hall floor has an L-shaped layout: 14 m overall length by 10 m overall width. A cutout corner measures 6 m by 4 m. A tin of floor varnish covers 25 m² and costs £34.99. How many tins must be bought, and what is the total cost?', 'marks': 4, 'weight': 1.4}], 18: [{'q': '<b>Question 1 (Foundation):</b> Calculate the area of a circular patio with a diameter of 6 metres. Give your answer to 2 decimal places. (Use π = 3.142)', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A semicircular lawn has a straight diameter edge of 10 metres. Lawn turf costs £5.80 per m². Calculate the cost to turf the semicircular lawn. (Use π = 3.142)', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A rectangular park area measuring 20 m by 14 m contains a circular ornamental pond of radius 4 m. The area outside the pond is covered in gravel at 40 kg per m². How many 800 kg bulk bags of gravel must be ordered? (Use π = 3.142)', 'marks': 4, 'weight': 1.4}], 19: [{'q': '<b>Question 1 (Foundation):</b> Calculate the total surface area of a cuboid measuring 12 cm long, 8 cm wide, and 5 cm high.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A triangular prism has identical right-angled triangular ends with base 6 cm, height 8 cm, and hypotenuse 10 cm. The prism is 15 cm long. Calculate its total surface area.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A manufacturer designs an open-topped cylindrical metal bin with diameter 40 cm and height 75 cm. The exterior of the base and curved side is powder-coated. What surface area in square metres must be coated? (Use π = 3.142)', 'marks': 4, 'weight': 1.4}], 20: [{'q': '<b>Question 1 (Foundation):</b> Calculate the volume of a triangular prism where the cross-sectional triangle has base 8 cm and height 5 cm, and the length is 22 cm.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A cylindrical oil barrel has a diameter of 60 cm and a height of 90 cm. Calculate its capacity in litres to 1 decimal place. (Use π = 3.14)', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A swimming pool measures 12 m long and 6 m wide. The shallow end is 1.0 m deep and slopes uniformly to 2.2 m at the deep end. Calculate the total volume of water in the pool in cubic metres and litres.', 'marks': 4, 'weight': 1.4}], 21: [{'q': '<b>Question 1 (Foundation):</b> A scale drawing uses the scale 1 : 20. A doorway is 90 cm wide in reality. What is its width on the drawing in centimetres?', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> Ship A sails from port on a bearing of 065°. What is the back bearing that Ship A must follow to return directly to the port?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A site surveyor creates a site plan using a scale of 1 : 200. On the plan, a rectangular warehouse boundary measures 18.5 cm by 12.0 cm. Calculate the real perimeter of the boundary in metres, and its real ground area in square metres.', 'marks': 4, 'weight': 1.4}], 22: [{'q': '<b>Question 1 (Foundation):</b> Calculate the mean, median, mode, and range for: 6, 9, 14, 8, 12, 9, 15, 7.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A sales representative has a mean monthly sales figure of £18,500 across 5 months. In the 6th month, she sells £24,500. Calculate her new 6-month mean.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> Two delivery depots recorded delivery delays (minutes) over 7 days. Depot North: 12, 15, 10, 8, 14, 11, 13. Depot South: 4, 25, 2, 30, 5, 28, 3. Calculate the mean and range for both depots, and write two comparison statements to advise the operations director.', 'marks': 4, 'weight': 1.4}], 23: [{'q': '<b>Question 1 (Foundation):</b> A survey recorded distance travelled to work: 0-5 km (12 people), 5-10 km (20 people), 10-15 km (8 people). Calculate the estimated mean distance.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> From the survey above, state the modal class interval and identify the interval containing the median.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> An Amazon fulfillment centre logs package weights: 0 < w ≤ 2 kg (45 packages), 2 < w ≤ 4 kg (80 packages), 4 < w ≤ 6 kg (55 packages), 6 < w ≤ 8 kg (20 packages). Calculate the estimated mean weight of a package and explain why this value is an estimate rather than an exact average.', 'marks': 4, 'weight': 1.4}], 24: [{'q': '<b>Question 1 (Foundation):</b> State the type of correlation you would expect between: a) Engine size and fuel consumption &emsp; b) Daily rainfall and ice cream sales.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A scatter graph shows employee training hours and error rates. The line of best fit has points (10, 18) and (30, 6). What error rate is predicted for an employee with 20 training hours?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A fitness coach plots body fat percentage against minutes taken to run 5 km for 12 athletes. An outlier is noted at (12%, 38 mins). Explain what an outlier is, whether it should be included when drawing the line of best fit, and what conclusion can be drawn from the remaining data points.', 'marks': 4, 'weight': 1.4}], 25: [{'q': '<b>Question 1 (Foundation):</b> 80 candidates took a driving test: 45 were female. 26 females passed. 12 males failed. Complete a two-way frequency table showing gender and test result.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> From the table above, what percentage of the male candidates passed the driving test? Give your answer to 1 decimal place.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A transport company audits 120 vehicle maintenance logs categorized by Vehicle Type (Van, Lorry) and Inspection Result (First-Time Pass, Minor Advisory, Major Fail). 70 vehicles are Vans. Of the Vans, 42 passed first time and 10 had major fails. Of the Lorries, 18 had minor advisories and 12 had major fails. Complete the table and find the probability that a randomly chosen Lorry passed first time.', 'marks': 4, 'weight': 1.4}], 26: [{'q': '<b>Question 1 (Foundation):</b> A hotel survey of 120 guests showed: Business (40), Holiday (60), Event (20). Calculate the angle for each sector.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> In a pie chart representing 1,800 voters, the sector for Candidate A has an angle of 108°. How many people voted for Candidate A?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A local council spends an annual transport budget of £2.4 million. In a pie chart, Highway Maintenance is allocated 135°, Public Buses 90°, Cycle Lanes 45°, and Pedestrian Paths 90°. Calculate the actual expenditure on Cycle Lanes and express it as a percentage of the total budget.', 'marks': 4, 'weight': 1.4}], 27: [{'q': '<b>Question 1 (Foundation):</b> A fair 6-sided dice is rolled. What is the probability of rolling: a) A prime number (2, 3, 5) &emsp; b) A number greater than 4?', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> In a factory quality check of 450 components, 18 are found to have minor defects. What is the relative frequency (probability) of picking a defect-free component? In a batch of 2,500 components, how many would you expect to have minor defects?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> Two independent machines operate on an assembly line. Machine A has a 0.90 probability of running without fault, and Machine B has a 0.85 probability of running without fault. Calculate the probability that BOTH machines run without fault on the same shift.', 'marks': 4, 'weight': 1.4}], 28: [{'q': '<b>Question 1 (Foundation):</b> An apprentice takes a theory test (pass probability 0.8) and a practical test (pass probability 0.7). Draw or list the 4 branch outcomes and find the probability of failing both.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> From Question 1, calculate the probability that the apprentice passes exactly one of the two tests.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 3 (Exam Challenge):</b> A weather forecaster predicts a 40% chance of rain on Saturday (0.4). If it rains on Saturday, the chance of rain on Sunday is 70% (0.7). If it does not rain on Saturday, the chance of rain on Sunday is 20% (0.2). Calculate the probability that it rains on at least one day over the weekend.', 'marks': 4, 'weight': 1.4}]}

CHECKPOINT_L2_QUESTIONS = {(0, 0): [{'q': '<b>Question 1:</b> Calculate without using a calculator: 416 × 28. Show your full column method.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 2:</b> A freezer compartment is at -14°C. The thermostat is adjusted so the temperature rises by 6.5°C, then drops by 3.2°C. What is the new temperature?', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 3:</b> Evaluate giving your answer as a mixed number in simplest form: 1 3/5 + 2 1/4.', 'marks': 2, 'weight': 1.0}], (0, 1): [{'q': '<b>Question 4:</b> Work out: 3,744 ÷ 13. Show your full written division method.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 5:</b> A tradesperson quotes £420.00 excluding VAT. VAT is charged at 20%. How much is the total quote with VAT included?', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 6:</b> Share £1,260 between three apprentices in the ratio 3 : 2 : 1. How much does the apprentice with the smallest share receive?', 'marks': 2, 'weight': 1.0}], (0, 2): [{'q': '<b>Question 7:</b> A sports retailer sells running shoes for £68.00 after a 15% discount. Calculate the original full price before the discount was applied.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 8:</b> A company deposits £15,000 in a business growth account offering 3.8% compound interest per year for 3 years. Calculate the total balance in the account at the end of the 3 years.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 9:</b> It takes 4 assembly technicians 15 hours to assemble a batch of medical ventilators. The hospital requests the batch in 10 hours. How many technicians in total are required?', 'marks': 3, 'weight': 1.2}], (0, 3): [{'q': '<b>Question 10:</b> A concrete mix requires sand, ballast, and cement in the ratio 5 : 3 : 2. A builder prepares 3.6 tonnes of mix. He has 1.7 tonnes of sand in stock. Does he have enough sand? Show full working.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 11:</b> A logistics manager bought an electric delivery van for £32,000. It depreciates by 16% in the first year and 12% in the second year. What is the value of the van at the end of year 2?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 12:</b> An office manager checks an invoice: 12 desks at £145.50 each, 24 chairs at £68.00 each. A delivery charge of £45.00 is added. A bulk discount of 7.5% is deducted from the total before adding 20% VAT. What is the final invoice total?', 'marks': 3, 'weight': 1.2}], (1, 0): [{'q': '<b>Question 1:</b> A delivery truck travels 135 miles in 2 hours 15 minutes. Calculate its average speed in miles per hour.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 2:</b> Convert: a) 4.2 kg to grams &emsp; b) 650 ml to litres &emsp; c) 25 miles to km using 5 miles = 8 km.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 3:</b> A circle has a diameter of 14 cm. Using π = 22/7, calculate: a) its circumference &emsp; b) its area.', 'marks': 2, 'weight': 1.0}], (1, 1): [{'q': '<b>Question 4:</b> A rectangular courtyard measures 12 m by 8.5 m. In the centre is a square fountain with sides of 2.5 m. Calculate the paved area of the courtyard.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 5:</b> A clock shows 09:35. An online training conference lasts for 3 hours 48 minutes. At what time does the conference end? (Use 24-hour clock format)', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 6:</b> A warehouse worker earns £12.50 per hour for 36 hours. Overtime is paid at time-and-a-half. In one week he works 4 hours overtime. What is his gross pay?', 'marks': 2, 'weight': 1.0}], (1, 2): [{'q': '<b>Question 7:</b> A commercial grain silo is shaped as a cylinder with diameter 4.2 m and height 8.5 m. Calculate the volume of the silo in cubic metres to 1 decimal place. (Use π = 3.142)', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 8:</b> A metal casting has a mass of 3,570 g and a volume of 420 cm³. Calculate its density in g/cm³. If pure zinc has a density of 7.14 g/cm³, determine whether the casting is pure zinc.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 9:</b> On a map with a scale of 1 : 25,000, the distance between two telecommunication masts is 16.4 cm. Calculate the actual distance between the masts in kilometres.', 'marks': 3, 'weight': 1.2}], (1, 3): [{'q': '<b>Question 10:</b> An office worker earns £34,000 gross per year. The tax-free personal allowance is £12,570. Basic rate income tax is charged at 20%. Employee National Insurance is 8% on earnings above £12,570. Calculate her total monthly take-home pay after tax and NI.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 11:</b> A lawn is in the shape of a trapezium with parallel sides 14 m and 22 m, and perpendicular distance 12 m. Grass seed costs £6.40 per box. Each box covers 25 m². How much does it cost to seed the entire lawn?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 12:</b> A heating engineer installs a closed cylindrical thermal expansion vessel: radius 0.35 m and height 1.2 m. The entire exterior surface is insulated with thermal foil costing £14.50/m². Calculate the cost of the foil. (Use π = 3.142)', 'marks': 3, 'weight': 1.2}], (2, 0): [{'q': '<b>Question 1:</b> The table shows the number of patients seen at a dental practice: Mon 24, Tue 32, Wed 28, Thu 36, Fri 30. Calculate: a) the mean &emsp; b) the range.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 2:</b> A spinner has 8 equal sections numbered 1 to 8. Calculate the probability of spinning: a) an even number &emsp; b) a multiple of 3.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 3:</b> 60 office workers were surveyed on their preferred lunch option: Sandwiches (30), Hot Food (20), Salad (10). Calculate the pie chart sector angle for each option.', 'marks': 2, 'weight': 1.0}], (2, 1): [{'q': '<b>Question 4:</b> A box contains 5 red pens, 7 blue pens, and 8 black pens. A pen is picked at random. What is the probability that it is NOT red? Give your answer as a fraction in simplest form.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 5:</b> The test marks of 9 apprentices are: 45, 52, 58, 61, 64, 68, 72, 75, 85. Find: a) the median mark &emsp; b) the interquartile range.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 6:</b> State whether each pair of variables has positive, negative, or no correlation: a) Daily sunshine hours and solar panel output &emsp; b) Car engine mileage and market resale value.', 'marks': 2, 'weight': 1.0}], (2, 2): [{'q': '<b>Question 7:</b> A delivery depot records the delivery times (t mins) for 50 consignments: 0 < t ≤ 10 (12), 10 < t ≤ 20 (22), 20 < t ≤ 30 (11), 30 < t ≤ 40 (5). Calculate the estimated mean delivery time.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 8:</b> A quality assurance inspector tests computer microchips. Machine A produces 60% of chips with a 2% defect rate. Machine B produces 40% of chips with a 5% defect rate. What is the overall probability that a randomly chosen chip is defective?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 9:</b> A scatter graph plots vehicle weight (kg) against fuel economy (mpg). The line of best fit passes through (1200, 48) and (1800, 32). Predict the fuel economy for a vehicle weighing 1500 kg, and describe the relationship.', 'marks': 3, 'weight': 1.2}], (2, 3): [{'q': '<b>Question 10:</b> A supermarket manager audits 200 customer transactions. 120 customers paid by contactless card, 50 by mobile app, and 30 in cash. Of the contactless users, 40% spent over £30. Of the mobile app users, 60% spent over £30. Construct a two-way table and find the probability that a customer picked at random spent over £30.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 11:</b> Two recruitment consultants interview candidates. Consultant X rates 8 candidates with a mean score of 72. Consultant Y rates 12 candidates with a mean score of 65. Calculate the combined mean score for all 20 candidates.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 12:</b> The probability of train service A being delayed is 0.20. The probability of train service B being delayed is 0.15. Assuming delays are independent, calculate the probability that at least one train is on time.', 'marks': 3, 'weight': 1.2}]}

MOCK_MATHS_L2_DATA = [{'sec_a': [[{'q': '<b>Question 1:</b> Calculate without using a calculator: 648 × 35. Show your full written method.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 2:</b> Evaluate giving your answer as a mixed number in simplest form: 2 2/3 ÷ 4/9.', 'marks': 2, 'weight': 1.0}], [{'q': '<b>Question 3:</b> A kitchen fitter cuts a circular hole with diameter 28 cm in a wooden worktop. Using π = 22/7, calculate the perimeter (circumference) of the cut hole.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 4:</b> An invoice shows a power saw sold for £264.00 including 20% VAT. Calculate the cost of the saw before VAT was added.', 'marks': 3, 'weight': 1.2}], [{'q': '<b>Question 5:</b> A healthcare assistant prepares 750 ml of saline infusion. Each dose is 60 ml. How many full doses can be administered, and how many millilitres remain?', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 6:</b> Share £2,400 between three apprentices in the ratio 4 : 3 : 1. What is the difference between the largest share and the smallest share?', 'marks': 3, 'weight': 1.2}]], 'sec_b': [[{'q': '<b>Question 7:</b> A senior nurse has a gross salary of £36,570. The personal allowance is £12,570. Basic rate income tax is 20%. National Insurance is 8% of earnings above £12,570. A workplace pension deduction of 6% of gross salary is made. Calculate her net monthly take-home pay.', 'marks': 4, 'weight': 1.3}, {'q': '<b>Question 8:</b> An engineering firm purchases a computerized CNC milling machine for £45,000. The machine depreciates at a compound rate of 15% per annum. Calculate the book value of the machine after 3 years.', 'marks': 4, 'weight': 1.3}], [{'q': "<b>Question 9:</b> A heavy haulage transporter travels 168 miles. The driver leaves depot at 06:15 and takes a mandatory 45-minute rest break during the journey. The vehicle arrives at 10:30. Calculate the driver's average driving speed in mph while moving.", 'marks': 4, 'weight': 1.3}, {'q': '<b>Question 10:</b> A landscape contractor constructs a patio in the shape of a trapezium with parallel sides 8.5 m and 13.5 m, and perpendicular height 6.4 m. Paving slabs cost £28.50 per square metre. Sand and mortar bedding adds £4.50 per square metre. Calculate the total material cost.', 'marks': 4, 'weight': 1.3}], [{'q': '<b>Question 11:</b> A commercial stainless-steel cylindrical storage tank has an internal diameter of 2.4 m and a height of 3.5 m. Calculate the liquid capacity of the tank in litres. (Use π = 3.142)', 'marks': 4, 'weight': 1.3}, {'q': '<b>Question 12:</b> A local council tracks response times (hours) for emergency housing repairs: 0 < h ≤ 12 (18 calls), 12 < h ≤ 24 (32 calls), 24 < h ≤ 36 (14 calls), 36 < h ≤ 48 (6 calls). Calculate the estimated mean response time in hours.', 'marks': 4, 'weight': 1.3}], [{'q': '<b>Question 13:</b> An architect designs an executive office suite: 12 m long by 8.5 m wide. A circular glass conference booth of diameter 4 m is located in the corner. The remaining floor space is carpeted with luxury tiles costing £32.00/m². VAT at 20% is added to the carpet cost. Calculate the total cost to carpet the office suite. (Use π = 3.142)', 'marks': 5, 'weight': 1.3}, {'q': '<b>Question 14:</b> On an ordnance survey map drawn to a scale of 1 : 25,000, a wildlife reserve boundary is a rectangle measuring 14.8 cm by 9.2 cm. Calculate the real perimeter of the reserve in kilometres, and the real land area of the reserve in square kilometres.', 'marks': 5, 'weight': 1.3}], [{'q': '<b>Question 15:</b> A healthcare audit tracks 150 clinic patients tested for diabetes: 90 patients are over 50 years old. Of those over 50, 27 tested positive. Of those aged 50 or under, 12 tested positive. Construct a complete two-way table. A patient is chosen at random from those who tested positive. What is the probability that this patient is aged 50 or under?', 'marks': 5, 'weight': 1.3}, {'q': '<b>Question 16:</b> A manufacturing plant produces precision steel rods. A sample of 100 rods has a mean length of 148.5 mm with a range of 4.2 mm. A second production line produces 100 rods with a mean length of 148.4 mm with a range of 1.1 mm. The target length is 148.5 mm. Compare the performance of the two production lines and advise the plant manager which line produces higher quality output.', 'marks': 5, 'weight': 1.3}]]}, {'sec_a': [[{'q': '<b>Question 1:</b> Calculate: <code>684 &divide; 18</code> without using a calculator. Show your full working.', 'marks': 4, 'weight': 1.2}, {'q': '<b>Question 2:</b> A pallet measures 1.2 m by 0.8 m. A warehouse floor is 24 m by 16 m. Calculate the maximum number of pallets that can fit on the floor in a single layer.', 'marks': 4, 'weight': 1.2}], [{'q': '<b>Question 3:</b> Calculate: <code>3/5 &times; 4/7</code>. Express your answer in simplest form.', 'marks': 4, 'weight': 1.2}, {'q': "<b>Question 4:</b> A delivery driver's hourly rate increased from £12.50 to £13.75. Calculate the percentage pay increase. Check your answer.", 'marks': 4, 'weight': 1.2}], [{'q': '<b>Question 1:</b> Calculate: <code>345.8 - 187.94</code> without a calculator. Show columnar working.', 'marks': 4, 'weight': 1.2}, {'q': '<b>Question 2:</b> A retailer buys stock for £450 and sells it for £630. Calculate the percentage profit margin on cost.', 'marks': 4, 'weight': 1.2}]], 'sec_b': [[{'q': '<b>Question 5: Fleet Fuel Efficiency:</b> Van A travels 420 miles on 60 litres of fuel. Van B travels 385 miles on 52 litres. Which van achieves better miles-per-gallon (mpg)? (1 gallon = 4.55 litres).', 'marks': 5, 'weight': 1.3}, {'q': '<b>Question 6: Cargo Weight & Density:</b> A container has volume 36 m&sup3;. It is loaded with cargo having an average density of 650 kg/m&sup3;. The maximum payload limit is 24 tonnes. Is the container overloaded?', 'marks': 5, 'weight': 1.3}], [{'q': '<b>Question 7: Courier Delivery Routes:</b> Driver covers 168 miles in 3 hours 30 mins. A 45-minute delivery stop was included. What was the driving speed while moving?', 'marks': 5, 'weight': 1.3}, {'q': '<b>Question 8: Forklift Ramp Slope:</b> A loading ramp rises 1.2 m over a horizontal distance of 5 m. Calculate the length of the sloping surface using Pythagoras (a&sup2; + b&sup2; = c&sup2;).', 'marks': 5, 'weight': 1.3}], [{'q': '<b>Question 9: Delivery Time Statistics:</b> Delivery times (mins): 10-19 (5), 20-29 (14), 30-39 (21), 40-49 (10). Calculate the estimated mean delivery time.', 'marks': 5, 'weight': 1.3}, {'q': '<b>Question 10: Warehouse Racking:</b> Racking is offered with a 12% discount. The discounted cost is £3,960. Find the original price before discount.', 'marks': 5, 'weight': 1.3}], [{'q': '<b>Question 11: Currency & Import:</b> A consignment from Germany costs €14,500. Customs import duty is 6%. If £1 = €1.15, calculate the total cost in GBP including duty.', 'marks': 5, 'weight': 1.3}, {'q': '<b>Question 12: Delivery Success Rate:</b> Out of 850 deliveries, 34 were failed deliveries. Calculate the percentage success rate to 1 decimal place.', 'marks': 5, 'weight': 1.3}], [{'q': '<b>Question 13: Storage Space Volume:</b> A cold storage room is 12m long, 8m wide, and 3.5m high. Industrial cooling requires 45 Watts per m&sup3;. What power cooling unit is required?', 'marks': 4, 'weight': 1.3}, {'q': "<b>Question 14: Van Tyre Replacement:</b> Tyres cost £95 each. A fleet replaces all 4 tyres on 15 vans. The supplier offers 'Buy 3 get 1 free' on every van. Calculate total cost.", 'marks': 4, 'weight': 1.3}]]}]

WORKBOOK_L2_DRILLS = {1: [{'q': '<b>Task 1: Rapid Warm-Up Drills:</b> Evaluate without a calculator:<br>       a) -14 + (-9) = ______________ &emsp; b) 12 - (-18) = ______________<br>       c) (-6) × (-7) = ____________ &emsp; d) (-72) ÷ (+8) = _____________', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Workplace Context &mdash; Commercial Overdraft:</b> A transport firm has a bank overdraft balance of <strong>-£2,340</strong> on Monday morning. During the week: client payment +£5,800, diesel fuel -£1,950, insurance direct debit -£780, and maintenance -£1,150. Calculate the closing balance.', 'marks': 3, 'weight': 1.3}], 2: [{'q': '<b>Task 1: Column Multiplication Warm-Up:</b> Calculate without using a calculator. Show your column or grid workings clearly:<br>       a) 348 × 27 &emsp;&emsp;&emsp;&emsp;&emsp;&emsp;&emsp;&emsp;&emsp;&emsp;&emsp;&emsp; b) 516 × 38', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Bus Stop Division with Decimals:</b> Divide <strong>918 by 24</strong> using short or long division. Give your answer as an exact decimal.', 'marks': 3, 'weight': 1.3}], 3: [{'q': '<b>Task 1: Fraction Operations Warm-Up:</b> Evaluate giving answers in simplest form: a) 5/12 + 3/8 &emsp; b) 2 1/4 - 1 2/3.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Joinery Construction Problem:</b> A joiner cuts two battens: 1 3/4 m and 2 3/8 m from a 5 m timber plank. What length of plank remains?', 'marks': 3, 'weight': 1.3}], 4: [{'q': '<b>Task 1: Multiplication &amp; Division Drills:</b> Evaluate giving answers in simplest form: a) 4/9 × 3/8 &emsp; b) 3 1/2 ÷ 7/10.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Commercial Bakery Batching:</b> A baker uses 2 1/4 kg of flour per cake batch. He has 18 kg of flour in stock. How many batches can he bake?', 'marks': 3, 'weight': 1.3}], 5: [{'q': '<b>Task 1: Decimal Arithmetic Warm-Up:</b> Calculate: a) 24.85 + 9.382 &emsp; b) 100 - 37.64 &emsp; c) 4.6 × 0.35 &emsp; d) 15.75 ÷ 0.5.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Mechanics Parts Invoice:</b> An auto garage invoice lists: 4 spark plugs at £14.25 each, brake pads at £68.50, and 2.5 hours labour at £42.00/hr. Find the pre-VAT total.', 'marks': 3, 'weight': 1.3}], 6: [{'q': '<b>Task 1: Multiplier Quick Fire:</b> State the single multiplier for: a) Increase by 17.5% &emsp; b) Decrease by 12% &emsp; c) Increase by 4.5% &emsp; d) Find 8.25%.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Retail Clearance Discount:</b> A television originally priced at £650.00 is discounted by 22%. Calculate the new sale price.', 'marks': 3, 'weight': 1.3}], 7: [{'q': '<b>Task 1: Reverse Multiplier Warm-Up:</b> Find the original value: a) Value after 20% increase is £144 &emsp; b) Value after 15% decrease is £204.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Pre-VAT Trade Price:</b> A tradesperson buys a cement mixer for £348.00 including 20% VAT. How much did the mixer cost before VAT was added?', 'marks': 3, 'weight': 1.3}], 8: [{'q': '<b>Task 1: Ratio Warm-Up Drills:</b> a) Share £560 in ratio 5 : 2. &emsp; b) Express the ratio 15 cm : 1.2 m in simplest form 1 : n.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Partnership Profits:</b> Two directors share company profit in ratio 7 : 4. Director A receives £21,000 more than Director B. What was total profit?', 'marks': 3, 'weight': 1.3}], 9: [{'q': '<b>Task 1: Inverse Proportion Warm-Up:</b> a) 4 builders take 6 days to lay paving. How long for 3 builders at same pace?<br>       b) A car at 60 mph takes 4 hours. How long at 48 mph?', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Unit Pricing Best Buy:</b> Paint Brand X: 5 litres for £28.50. Paint Brand Y: 7.5 litres for £41.25. Which offers better value per litre?', 'marks': 3, 'weight': 1.3}], 10: [{'q': '<b>Task 1: Compound Multiplier Drills:</b> Calculate: a) £4,000 at 3% compound interest for 2 years. &emsp; b) £12,000 depreciating at 10% for 3 years.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Fleet Van Depreciation:</b> A delivery van cost £24,000 brand new. It depreciates by 15% in year 1 and 12% in year 2. What is its value after 2 years?', 'marks': 3, 'weight': 1.3}], 11: [{'q': '<b>Task 1: BIDMAS &amp; Powers Warm-Up:</b> Evaluate: a) 18 - 4 × 3 + 5 &emsp; b) 2 × 3² - (10 - 4) &emsp; c) (45 - 3²) ÷ (4 + 2) &emsp; d) 5² - √64.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Mechanics Braking Formula:</b> Stopping distance formula: d = 0.05v² + 0.2v, where v = speed in mph. Find stopping distance at 60 mph.', 'marks': 3, 'weight': 1.3}], 12: [{'q': '<b>Task 1: Rapid Conversion Drills:</b> Convert: a) 4.8 kg into grams &emsp; b) 650 ml into litres &emsp; c) 2.4 m into cm &emsp; d) 35 miles to km (5 mi ≈ 8 km).', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Hospital Patient Medication:</b> A patient requires 15 ml of oral antibiotic 3 times daily for 10 days. How many 200 ml bottles must be dispensed?', 'marks': 3, 'weight': 1.3}], 13: [{'q': '<b>Task 1: Elapsed Time Warm-Up:</b> Find elapsed duration: a) 08:45 to 14:15 &emsp; b) 19:50 to 02:25 (next day).', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Train &amp; Meeting Connection:</b> A business consultant catches the 09:28 train. Travel time is 1 hr 45 mins, followed by a 15-minute taxi ride. Does she arrive before 11:30?', 'marks': 3, 'weight': 1.3}], 14: [{'q': '<b>Task 1: Overtime Rate Calculations:</b> Standard rate £12.40/hr. Find: a) Time-and-a-half rate &emsp; b) Double time rate &emsp; c) Pay for 35 normal hrs + 6 hrs at time-and-a-half.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Annual PAYE Income Tax:</b> A software developer earns £32,570 per annum. Personal allowance is £12,570. Basic rate tax is 20%. Calculate his annual income tax.', 'marks': 3, 'weight': 1.3}], 15: [{'q': '<b>Task 1: L-Shape Perimeter Warm-Up:</b> An L-shaped room has overall length 9 m and overall width 7 m. Cutout corner is 4 m by 3 m. Find its perimeter.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Skirting Board Cost:</b> A rectangular bedroom measures 4.8 m by 3.6 m. It has a 0.9 m door opening. Skirting board costs £4.50 per metre. Calculate cost.', 'marks': 3, 'weight': 1.3}], 16: [{'q': '<b>Task 1: Circumference Drills:</b> Calculate circumference (take π = 3.14): a) Circle with diameter 15 cm &emsp; b) Circle with radius 6.2 m.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Semicircular Flowerbed Border:</b> A garden has a semicircular flowerbed with diameter 8 m. Brick edging is placed around the entire perimeter. Calculate total length. (Use π = 3.142)', 'marks': 3, 'weight': 1.3}], 17: [{'q': '<b>Task 1: Area Formula Warm-Up:</b> Calculate area: a) Triangle: base 12 cm, height 7 cm &emsp; b) Parallelogram: base 9.5 m, perpendicular height 4.2 m.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Laminate Flooring &amp; 10% Wastage:</b> A dining room measures 5.4 m by 3.8 m. Flooring packs cover 2.2 m² each. Adding 10% for wastage, how many packs are needed?', 'marks': 3, 'weight': 1.3}], 18: [{'q': '<b>Task 1: Trapezium Area Warm-Up:</b> Calculate area: a) Trapezium: parallel sides 6 m and 10 m, height 4 m &emsp; b) Circle of radius 5 m (take π = 3.14).', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Paving Around a Circular Pond:</b> A square lawn of side 12 m has a circular pond of diameter 4 m in its centre. What is the area of grass remaining? (Use π = 3.142)', 'marks': 3, 'weight': 1.3}], 19: [{'q': '<b>Task 1: Cuboid Surface Area Warm-Up:</b> Calculate surface area: a) Cuboid 10 cm × 6 cm × 4 cm &emsp; b) Cube of side 5 cm.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Triangular Prism Tent Fabric:</b> A tent is a triangular prism. Triangular ends have base 2.4 m, height 1.6 m, and slant edges 2.0 m. Length is 3.5 m. Find total fabric area.', 'marks': 3, 'weight': 1.3}], 20: [{'q': '<b>Task 1: Volume Calculation Warm-Up:</b> Calculate volume: a) Cuboid 8 cm × 5 cm × 12 cm &emsp; b) Cylinder: radius 4 cm, height 10 cm (take π = 3.14).', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Water Storage Cistern:</b> A rectangular water tank is 1.8 m long, 1.2 m wide, and 0.8 m deep. How many litres of water does it hold when full?', 'marks': 3, 'weight': 1.3}], 21: [{'q': '<b>Task 1: Prism Volume Drills:</b> A prism has cross-sectional area 45 cm² and length 18 cm. What is its volume? If it is made of aluminium with density 2.7 g/cm³, find its mass.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Sloping Swimming Pool Volume:</b> A pool is 15 m long and 6 m wide. Depth slopes uniformly from 1.0 m to 2.0 m. Calculate total volume of water in cubic metres.', 'marks': 3, 'weight': 1.3}], 22: [{'q': '<b>Task 1: Scale Factor Warm-Up:</b> On a plan with scale 1 : 50: a) A wall is 6.5 cm on plan. Real length in metres? &emsp; b) A sofa is 1.8 m long in reality. Plan length in cm?', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Office Suite Floor Plan:</b> On a 1 : 75 scale drawing, an office measures 12 cm by 8 cm. Find its real ground floor area in square metres.', 'marks': 3, 'weight': 1.3}], 23: [{'q': '<b>Task 1: Bearings Basics Warm-Up:</b> Write as 3-figure bearings: a) North-East &emsp; b) South-West &emsp; c) Due West &emsp; d) 35° East of North.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Ship Course &amp; Return Bearing:</b> A coastguard cutter sails from port on a bearing of 078° to reach a vessel in distress. What bearing must it steer to return to port?', 'marks': 3, 'weight': 1.3}], 24: [{'q': '<b>Task 1: Formula Calculations Warm-Up:</b> a) Speed: 105 miles in 1 hr 45 mins. &emsp; b) Density: mass 840 g, volume 120 cm³.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Courier Van Delivery Route:</b> A delivery van travels 90 miles on a motorway at an average speed of 60 mph, then 15 miles through city traffic at 20 mph. Find total time.', 'marks': 3, 'weight': 1.3}], 25: [{'q': '<b>Task 1: Complete the Table:</b> 50 office workers surveyed on transport mode: 28 are Female. 12 Males drive. 18 Females take public transport. 6 Males walk. No Females walk. Complete the table.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Probability from Table:</b> From the table in Task 1, what fraction of Male workers drive? Give your answer in simplest form.', 'marks': 3, 'weight': 1.3}], 26: [{'q': "<b>Task 1: Read Dual Bar Chart:</b> A dual bar chart shows laptop sales (Units): Q1 (Store A: 120, Store B: 90); Q2 (Store A: 150, Store B: 180). Find total units sold and Store B's share.", 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Percentage Growth Comparison:</b> Store A sales grew from 120 to 150. Store B sales grew from 90 to 180. Calculate the percentage increase for both stores. Which grew faster?', 'marks': 3, 'weight': 1.3}], 27: [{'q': '<b>Task 1: Temperature Monitoring:</b> Patient temperature logged: 08:00 (38.6°C), 10:00 (38.2°C), 12:00 (37.4°C). Estimate temperature at 09:00.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Energy Consumption Trend:</b> Electricity meter reading: Mon 420 kWh, Tue 460 kWh, Wed 510 kWh, Thu 480 kWh, Fri 430 kWh. Find mean daily usage.', 'marks': 3, 'weight': 1.3}], 28: [{'q': '<b>Task 1: Sector Angle Calculations:</b> 90 employees travel to work: Car (45), Bus (25), Train (15), Cycle (5). Calculate the sector angle for each travel mode.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Extracting Values from Angle:</b> In a pie chart of 1,200 voters, the sector for Candidate Green has an angle of 54°. How many people voted for Candidate Green?', 'marks': 3, 'weight': 1.3}], 29: [{'q': '<b>Task 1: Calculate the 4 Measures:</b> For data set: 14, 18, 12, 25, 18, 16, 23. Find: a) Mean &emsp; b) Median &emsp; c) Mode &emsp; d) Range.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Adding a New Value to Mean:</b> A call centre agent has a mean call time of 4.5 minutes across 8 calls. Her 9th call lasts 9.0 minutes. What is her new mean?', 'marks': 3, 'weight': 1.3}], 30: [{'q': '<b>Task 1: Midpoints &amp; Products Warm-Up:</b> Classes: 0-10 (freq 4), 10-20 (freq 11), 20-30 (freq 5). State midpoints and calculate Sum(fx).', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Estimated Mean Calculation:</b> Using Task 1 above, calculate the estimated mean. Why is this an estimate?', 'marks': 3, 'weight': 1.3}], 31: [{'q': '<b>Task 1: Delivery Driver Performance:</b> Driver X: Mean deliveries = 32, Range = 4. Driver Y: Mean deliveries = 36, Range = 15. Compare their performance.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Hospital Waiting Times:</b> Hospital A median wait = 42 mins, IQR = 15 mins. Hospital B median wait = 35 mins, IQR = 28 mins. Advise a patient.', 'marks': 3, 'weight': 1.3}], 32: [{'q': '<b>Task 1: Correlation Identification:</b> State correlation: a) Revision hours and exam score &emsp; b) Car engine size and mpg &emsp; c) Shoe size and salary.', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Reading Line of Best Fit:</b> A scatter graph relates temperature (°C) to cold drinks sold. The line passes through (15, 60) and (25, 100). Predict drinks at 20°C.', 'marks': 3, 'weight': 1.3}], 33: [{'q': '<b>Task 1: Basic Probability Drills:</b> A box has 8 red, 5 green, 7 blue counters. A counter is chosen at random: a) P(Red) &emsp; b) P(Not Green) &emsp; c) P(Yellow).', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Independent Combined Probability:</b> A fair coin is flipped and a standard 6-sided dice is rolled. What is the probability of getting a Head and a 6?', 'marks': 3, 'weight': 1.3}], 34: [{'q': '<b>Task 1: Complete Tree Branches:</b> Candidate sits two tests: P(Pass 1st) = 0.8. If pass, P(Pass 2nd) = 0.7. If fail, P(Pass 2nd) = 0.4. Find P(Pass both).', 'marks': 4, 'weight': 1.0}, {'q': '<b>Task 2: Weather &amp; Commute Delay:</b> P(Rain) = 0.3. If rain, P(Late) = 0.6. If dry, P(Late) = 0.1. Calculate total probability of being late.', 'marks': 3, 'weight': 1.3}]}

TOPIC_L1_QUESTIONS = {1: [{'q': "<b>Question 1 (Foundation):</b> Write 'Forty-five thousand, eight hundred and twenty' in figures.", 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A factory produced 128,450 units in March and 95,200 units in April. How many more units were produced in March?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> Put these warehouse stock counts in order from smallest to largest: 14,200; 3,450; 108,500; 12,890.', 'marks': 3, 'weight': 1.3}], 2: [{'q': '<b>Question 1 (Foundation):</b> Order these temperatures from coldest to warmest: +4°C, −8°C, −2°C, 0°C, −11°C.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A cold store is at −15°C. When the loading door opens, the temperature rises by 6°C. What is the new temperature?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A trader has a bank balance of £120. A bill of £185 is taken from the account. What is the new balance, and how much must be paid in to reach +£50?', 'marks': 3, 'weight': 1.3}], 3: [{'q': '<b>Question 1 (Foundation):</b> Calculate without a calculator: 4,850 + 2,680.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A tradesperson buys three tool accessories costing £24.50, £18.75, and £9.20. Calculate the total cost.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A department has a monthly stationery budget of £1,500. They spend £845 on paper and £320 on toner cartridges. How much budget remains?', 'marks': 3, 'weight': 1.3}], 4: [{'q': '<b>Question 1 (Foundation):</b> Calculate without using a calculator: 145 × 18.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A warehouse receives 24 crates of parts. Each crate holds 35 items. How many items are delivered in total?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> An operative works 32 hours in a week at an hourly rate of £12.50. Calculate their total weekly gross pay.', 'marks': 3, 'weight': 1.3}], 5: [{'q': '<b>Question 1 (Foundation):</b> Calculate without a calculator: 256 ÷ 8.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A dispatch team must pack 185 components into crates that hold 12 components each. How many crates are needed to pack all 185 components?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> Four staff members share a £350 team bonus equally. How much does each person receive?', 'marks': 3, 'weight': 1.3}], 6: [{'q': '<b>Question 1 (Foundation):</b> Calculate 1/4 of £240.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A building load weighs 480 kg. A crane lifts 3/4 of this weight in the first load. How many kilograms does it lift?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A training session lasts 90 minutes. 2/3 of the session is spent on practical tasks. How many minutes are spent on practical tasks?', 'marks': 3, 'weight': 1.3}], 7: [{'q': '<b>Question 1 (Foundation):</b> Round 14.86 metres to 1 decimal place.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A customer buys items costing £3.45 and £8.80. Calculate the total bill.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A joiner cuts a 1.85 m piece from a 4.2 m timber batten. What length of batten is left in metres?', 'marks': 3, 'weight': 1.3}], 8: [{'q': '<b>Question 1 (Foundation):</b> Calculate 10% of £450.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A jacket priced at £180 is reduced by 25% in a clearance sale. Calculate the new sale price.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A company employs 320 staff. 75% of the staff completed fire safety training this week. How many staff completed the training?', 'marks': 3, 'weight': 1.3}], 9: [{'q': '<b>Question 1 (Foundation):</b> Share £180 between two charities in the ratio 2 : 1.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A builder mixes cement and sand in the ratio 1 : 4. How much cement and how much sand are in a 25 kg bag of mix?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A decorator mixes white and blue paint in the ratio 2 : 1 to make 6 litres of light blue paint. How many litres of each colour are used?', 'marks': 3, 'weight': 1.3}], 10: [{'q': '<b>Question 1 (Foundation):</b> A soup recipe for 4 people uses 600 ml of vegetable stock. How much stock is needed to make the soup for 6 people?', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> Three identical training manuals cost £24.00. How much do five training manuals cost?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A cake recipe for 8 portions needs 250 g of flour and 150 g of sugar. How much flour and sugar are needed for 16 portions?', 'marks': 3, 'weight': 1.3}], 11: [{'q': '<b>Question 1 (Foundation):</b> Round each number to the nearest 10 to estimate: 49 × 21.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> Estimate the total cost of 19 high-visibility vests at £11.85 each by rounding both numbers.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A warehouse had 500 boxes and dispatched 184 boxes, leaving 316 boxes. Write down a reverse addition calculation to check that 316 is correct.', 'marks': 3, 'weight': 1.3}], 12: [{'q': '<b>Question 1 (Foundation):</b> A shopper buys items costing £3.45, £2.80, and £6.15. How much change do they receive from a £20 note?', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A customer pays for a £34.20 meal with a £50 note. Calculate the change due.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> An apprentice buys 3 packs of drill bits at £4.50 per pack and pays with a £20 note. Calculate the total cost and the change given.', 'marks': 3, 'weight': 1.3}], 13: [{'q': '<b>Question 1 (Foundation):</b> Convert: a) 3:15 pm to 24-hour clock &emsp; b) 19:40 to 12-hour am/pm clock.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A hospital shift starts at 08:30 and ends at 16:45. How long is the shift in hours and minutes?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A staff training meeting starts at 14:30 and lasts for 1 hour 45 minutes. At what time does the meeting finish?', 'marks': 3, 'weight': 1.3}], 14: [{'q': '<b>Question 1 (Foundation):</b> A bus departs High Street at 14:22 and arrives at the Hospital at 14:58. How many minutes does the journey take?', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> Trains leave Station A at 10:05, 10:32, and 11:02, taking 33 minutes to reach Station B. If you arrive at Station A at 10:15, when will you reach Station B?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A coach leaves London at 09:45 and arrives in Oxford at 11:03. Calculate the total journey time in hours and minutes.', 'marks': 3, 'weight': 1.3}], 15: [{'q': '<b>Question 1 (Foundation):</b> Convert: a) 2.4 metres into centimetres &emsp; b) 45 millimetres into centimetres.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> From a 3.6 m length of timber, a carpenter cuts 4 pieces each measuring 65 cm. What length of timber remains in metres?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A charity runner completes a 5.2 km run. How many metres is this in total?', 'marks': 3, 'weight': 1.3}], 16: [{'q': '<b>Question 1 (Foundation):</b> Convert 1,750 grams into kilograms.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A courier packs 4 parcels, each weighing 350 grams. What is the total weight of the 4 parcels in kilograms?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A chef has a 2.5 kg bag of flour and uses 800 grams for a batch of bread. How many kilograms of flour remain in the bag?', 'marks': 3, 'weight': 1.3}], 17: [{'q': '<b>Question 1 (Foundation):</b> Convert 4.5 litres into millilitres.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A catering urn dispenses 15 cups of tea, each holding 250 ml. How many litres of tea were dispensed altogether?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A cleaner mixes 500 ml of disinfectant concentrate with 4.5 litres of water. What is the total volume of the diluted solution in litres?', 'marks': 3, 'weight': 1.3}], 18: [{'q': '<b>Question 1 (Foundation):</b> Calculate the perimeter of a rectangular garden measuring 9 metres long by 6 metres wide.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A rectangular bedroom measures 4.5 m by 3.2 m. Calculate the total perimeter of the room.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A rectangular car park measures 15 metres long by 9 metres wide. Calculate the total length of boundary fencing needed.', 'marks': 3, 'weight': 1.3}], 19: [{'q': '<b>Question 1 (Foundation):</b> Calculate the area of a floor measuring 4.5 metres long by 3 metres wide.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A wall measures 6 metres long by 2.5 metres high. Calculate its area, and find the total area to be painted if 2 coats are required.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A rectangular office measures 8 metres by 5 metres. Carpet tiles cost £12 per square metre. Calculate the floor area and total cost.', 'marks': 3, 'weight': 1.3}], 20: [{'q': '<b>Question 1 (Foundation):</b> Name the 3D shape that has 6 rectangular faces, 12 edges, and 8 vertices.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> How many degrees are in a right angle and in a straight line?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> State the number of faces, edges, and vertices on a triangular prism.', 'marks': 3, 'weight': 1.3}], 21: [{'q': '<b>Question 1 (Foundation):</b> You are facing North and turn 90° clockwise. Which compass direction are you now facing?', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> Which compass direction is directly opposite South-West?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> A delivery driver is heading East and makes a 180° turn. Which direction is the driver now travelling?', 'marks': 3, 'weight': 1.3}], 22: [{'q': '<b>Question 1 (Foundation):</b> Explain how 14 is written in tally marks using bundles of five.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A traffic count records: Car (8), Van (14), Bus (12), Bike (6). Calculate the total frequency of vehicles.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> From the traffic count in Question 2, which vehicle category is the most popular (the mode)?', 'marks': 3, 'weight': 1.3}], 23: [{'q': '<b>Question 1 (Foundation):</b> A bar chart shows 25 sales on Monday and 40 sales on Wednesday. How many more sales were made on Wednesday?', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> On a bar chart axis, 4 grid squares represent 20 units. How many units does 1 grid square represent?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> Daily sales from Monday to Friday are: 25, 30, 40, 35, 35. Calculate the total weekly sales.', 'marks': 3, 'weight': 1.3}], 24: [{'q': '<b>Question 1 (Foundation):</b> A pictogram key shows 1 circle = 8 cars. How many cars are represented by 3.5 circles?', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> If 1 symbol represents 4 bicycles, how many symbols are needed to show 20 bicycles?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> In the car pictogram (1 circle = 8 cars), Monday has 3 circles, Tuesday has 2.5 circles, and Wednesday has 3.5 circles. Find the total cars across all three days.', 'marks': 3, 'weight': 1.3}], 25: [{'q': '<b>Question 1 (Foundation):</b> An employee works 7, 8, 8, 9, and 8 hours over 5 days. Calculate the mean daily hours worked.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> Four learners score 15, 18, 21, and 26 on a safety test. Calculate the mean score.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> Over 4 weeks, a household spends £40, £45, £38, and £47 on electricity. Calculate the mean weekly spend.', 'marks': 3, 'weight': 1.3}], 26: [{'q': '<b>Question 1 (Foundation):</b> Daily call counts in an office are: 45, 62, 38, 55, 71, 49. Calculate the range of calls.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> Overnight temperatures were −4°C on Monday and +6°C on Friday. What is the temperature range?', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> Delivery times for 5 parcels were 18, 29, 45, 31, and 24 minutes. Calculate the range of the delivery times.', 'marks': 3, 'weight': 1.3}], 27: [{'q': '<b>Question 1 (Foundation):</b> A postage table shows: Letter £0.85, Large Letter £1.55, Small Parcel £3.29. Find the cost of sending 3 Small Parcels.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> A courier tariff table shows Standard Delivery (£4.50) and Express Next-Day (£8.95) for orders under £50. State the Standard Delivery charge.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> An invoice table lists: 4 chairs at £28.50 each and 1 table at £34.20. Calculate the total invoice amount.', 'marks': 3, 'weight': 1.3}], 28: [{'q': '<b>Question 1 (Foundation):</b> Use a probability word (Impossible, Unlikely, Evens, Likely, Certain) to describe rolling a number from 1 to 6 on a standard fair dice.', 'marks': 2}, {'q': '<b>Question 2 (Workplace Problem):</b> Describe the likelihood of flipping tails on a fair 50p coin.', 'marks': 2}, {'q': '<b>Question 3 (Exam Challenge):</b> Describe the likelihood of rolling an 8 on a standard 6-sided dice numbered 1 to 6.', 'marks': 3, 'weight': 1.3}]}

CHECKPOINT_L1_QUESTIONS = {(0, 0): [{'q': '<b>Question 1:</b> Calculate without using a calculator: 348 × 16. Show your full written method.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 2:</b> A bank account is overdrawn at -£185. The customer pays in £450. What is the new balance?', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 3:</b> Simplify fully: a) 18/24 &emsp; b) Write 3/5 as a percentage.', 'marks': 2, 'weight': 1.0}], (0, 1): [{'q': '<b>Question 4:</b> Work out: 1,476 ÷ 6 without a calculator. Show your bus stop division.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 5:</b> Evaluate: 20 - 4 × 3 + 2.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 6:</b> Share £120 in the ratio 3 : 1. What is the larger share?', 'marks': 2, 'weight': 1.0}], (0, 2): [{'q': '<b>Question 7:</b> A jacket costs £80. It is reduced by 15% in a sale. Calculate the sale price.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 8:</b> A recipe for 4 people requires 300 g of rice. How much rice is needed for 9 people?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 9:</b> A delivery company has 350 parcels to deliver. In the morning they deliver 3/5 of the parcels. How many parcels remain to be delivered in the afternoon?', 'marks': 3, 'weight': 1.2}], (0, 3): [{'q': '<b>Question 10:</b> An electrician charges: £45 call-out + (£32 × hours). He works for 4.5 hours. How much is the bill?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 11:</b> A supermarket sells a 6-pack of cola for £4.20 and a 10-pack of the same cola for £6.80. Which pack is better value per can? Show your calculations.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 12:</b> A landscape gardener orders 24 bags of decorative gravel at £6.75 each. Delivery is £25.00. He has a budget of £180.00. Does he have enough money?', 'marks': 3, 'weight': 1.2}], (1, 0): [{'q': '<b>Question 1:</b> Convert: a) 4.2 kg to grams &emsp; b) 650 ml to litres.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 2:</b> A train departs at 09:35 and arrives at 11:15. How long was the journey in hours and minutes?', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 3:</b> Calculate the perimeter of a rectangle measuring 8 m by 5.5 m.', 'marks': 2, 'weight': 1.0}], (1, 1): [{'q': '<b>Question 4:</b> Calculate the area of a square patio with side length 6 m.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 5:</b> A bottle of medicine holds 250 ml. A patient takes 15 ml per dose. How many full doses can be taken?', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 6:</b> State the number of faces, edges, and vertices on a cuboid.', 'marks': 2, 'weight': 1.0}], (1, 2): [{'q': '<b>Question 7:</b> A carpet costs £18.50 per square metre. A living room measures 5.4 m by 4.0 m. Calculate the cost of the carpet.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 8:</b> A delivery driver travels 30 miles. Using 5 miles = 8 km, convert this distance into kilometres.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 9:</b> A water cistern measures 1.2 m long, 0.8 m wide, and 0.6 m high. How many litres of water does it hold? (1 m³ = 1000 L)', 'marks': 3, 'weight': 1.2}], (1, 3): [{'q': '<b>Question 10:</b> A healthcare assistant works 32 basic hours at £11.20/hr, plus 5 hours overtime at time-and-a-half (£16.80/hr). What is her total pay?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 11:</b> On a map with scale 1 cm = 50 m, the distance between two bus stops is 7.4 cm. What is the real distance in metres?', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 12:</b> An L-shaped lawn has two sections: 6 m × 4 m and 3 m × 2 m. Grass seed costs £4.50 per box. Each box covers 10 m². How much does it cost to seed the lawn?', 'marks': 3, 'weight': 1.2}], (2, 0): [{'q': '<b>Question 1:</b> Test scores: 12, 18, 15, 11, 14. Calculate: a) Mean &emsp; b) Range.', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 2:</b> A spinner has 6 equal sections numbered 1 to 6. What is the probability of spinning an odd number?', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 3:</b> A tally chart records: <s>||||</s> <s>||||</s> |||. Write the frequency number.', 'marks': 2, 'weight': 1.0}], (2, 1): [{'q': '<b>Question 4:</b> In a bag there are 4 blue pens and 6 black pens. What is P(Blue) in simplest form?', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 5:</b> A bar chart shows sandwich sales: Ham 15, Cheese 25, Tuna 10. What is the modal sandwich?', 'marks': 2, 'weight': 1.0}, {'q': '<b>Question 6:</b> A conversion graph shows £10 = 12 Euros. Convert £30 to Euros.', 'marks': 2, 'weight': 1.0}], (2, 2): [{'q': '<b>Question 7:</b> A delivery depot records packages delivered: Mon 45, Tue 52, Wed 48, Thu 55, Fri 50. Calculate the mean daily deliveries.', 'marks': 3, 'weight': 1.2}, {'q': "<b>Question 8:</b> In a pie chart representing 120 people, the sector for 'Public Transport' has a right angle (90°). How many people take public transport?", 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 9:</b> A pictogram uses a circle symbol &#9679; = 8 cars. Monday shows 3 circles. Tuesday shows 2 1/2 circles. How many cars in total were washed over both days?', 'marks': 3, 'weight': 1.2}], (2, 3): [{'q': '<b>Question 10:</b> Team Alpha mean score is 42, range is 5. Team Beta mean score is 42, range is 16. Write two comparison statements.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 11:</b> A box holds 20 light bulbs: 2 are defective. What is the probability that a bulb chosen at random is NOT defective? Give your answer as a decimal.', 'marks': 3, 'weight': 1.2}, {'q': '<b>Question 12:</b> A survey asked 60 customers their preferred payment: Card (35), Cash (15), Phone App (10). What percentage preferred Card?', 'marks': 3, 'weight': 1.2}]}

